import{_ as p,a0 as l,w as r,s as o,ao as d,I as t,x as a,a1 as n,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何在 Ubuntu 22.04 / 20.04 上配置 FreeIPA 客户端 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Ubuntu 22.04 / 20.04 上配置 FreeIPA 客户端 | LCTT (202305) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Ubuntu 22.04 / 20.04 上配置 FreeIPA 客户端 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Ubuntu 22.04 / 20.04 上配置 FreeIPA 客户端 | LCTT (202305) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202305/20230416.0 ⭐️⭐️ How to Configure FreeIPA Client on Ubuntu 22.04  20.04","title":"如何在 Ubuntu 22.04 / 20.04 上配置 FreeIPA 客户端","tag":"202305","desc":""},"relativePath":"202305/20230416.0 ⭐️⭐️ How to Configure FreeIPA Client on Ubuntu 22.04  20.04.md","filePath":"[post].md"}'),u={name:"202305/20230416.0 ⭐️⭐️ How to Configure FreeIPA Client on Ubuntu 22.04  20.04.md"};function h(c,s,b,g,k,m){const e=l("Link");return r(),o("div",null,[s[15]||(s[15]=d(`<h1 id="如何在-ubuntu-22-04-20-04-上配置-freeipa-客户端" tabindex="-1">如何在 Ubuntu 22.04 / 20.04 上配置 FreeIPA 客户端 <a class="header-anchor" href="#如何在-ubuntu-22-04-20-04-上配置-freeipa-客户端" aria-label="Permalink to “如何在 Ubuntu 22.04 / 20.04 上配置 FreeIPA 客户端”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202305/27/154923gzbqexm0b1japa62.jpg" alt=""></p><p>FreeIPA 是一个强大的开源身份管理系统，提供集中的身份验证、授权和计费服务。在本文中，我们将逐步介绍在 Ubuntu 22.04 / 20.04 上配置 FreeIPA 客户端的步骤。配置 FreeIPA 客户端后，我们将尝试使用在 FreeIPA 服务器上创建的用户登录。</p><p>在我们之前的帖子中，我们已经讨论了 FreeIPA 服务器在 RHEL8/Rokcy Linux 8/ AlmaLinux 8 上的安装步骤。</p><h3 id="在-freeipa-服务器上创建用户进行集中认证" tabindex="-1">在 FreeIPA 服务器上创建用户进行集中认证 <a class="header-anchor" href="#在-freeipa-服务器上创建用户进行集中认证" aria-label="Permalink to “在 FreeIPA 服务器上创建用户进行集中认证”">​</a></h3><p>登录到你的 FreeIPA 服务器并创建一个名为 <code>sysadm</code> 的用户，运行以下命令:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo kinit admin</span></span>
<span class="line"><span>Password for admin@LINUXTECHI.LAN:</span></span>
<span class="line"><span>$</span></span>
<span class="line"><span>$ sudo ipa config-mod --defaultshell=/bin/bash</span></span>
<span class="line"><span>$ sudo ipa user-add sysadm --first=System --last=Admin --password</span></span>
<span class="line"><span>Password:</span></span>
<span class="line"><span>Enter Password again to verify:</span></span>
<span class="line"><span>-------------------</span></span>
<span class="line"><span>Added user &quot;sysadm&quot;</span></span>
<span class="line"><span>-------------------</span></span>
<span class="line"><span>User login: sysadm</span></span>
<span class="line"><span>First name: System</span></span>
<span class="line"><span>Last name: Admin</span></span>
<span class="line"><span>Full name: System Admin</span></span>
<span class="line"><span>Display name: System Admin</span></span>
<span class="line"><span>Initials: SA</span></span>
<span class="line"><span>Home directory: /home/sysadm</span></span>
<span class="line"><span>GECOS: System Admin</span></span>
<span class="line"><span>Login shell: /bin/bash</span></span>
<span class="line"><span>Principal name: sysadm@LINUXTECHI.LAN</span></span>
<span class="line"><span>Principal alias: sysadm@LINUXTECHI.LAN</span></span>
<span class="line"><span>User password expiration: 20230415073041Z</span></span>
<span class="line"><span>Email address: sysadm@linuxtechi.lan</span></span>
<span class="line"><span>UID: 464600003</span></span>
<span class="line"><span>GID: 464600003</span></span>
<span class="line"><span>Password: True</span></span>
<span class="line"><span>Member of groups: ipausers</span></span>
<span class="line"><span>Kerberos keys available: True</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>第一个命令是获取 Kerberos 凭证，第二个命令将所有用户的默认登录 shell 设置为 <code>/bin/bash</code>，第三个命令用于创建名为 <code>sysadm</code> 的用户。</p><h3 id="在-ubuntu-22-04-20-04-上配置-freeipa-客户端的步骤" tabindex="-1">在 Ubuntu 22.04 /20.04 上配置 FreeIPA 客户端的步骤 <a class="header-anchor" href="#在-ubuntu-22-04-20-04-上配置-freeipa-客户端的步骤" aria-label="Permalink to “在 Ubuntu 22.04 /20.04 上配置 FreeIPA 客户端的步骤”">​</a></h3><p>执行以下步骤来配置 FreeIPA 客户端以进行集中身份验证。</p><h4 id="_1、在-freeipa-服务器上添加-ubuntu-系统的-dns-记录" tabindex="-1">1、在 FreeIPA 服务器上添加 Ubuntu 系统的 DNS 记录 <a class="header-anchor" href="#_1、在-freeipa-服务器上添加-ubuntu-系统的-dns-记录" aria-label="Permalink to “1、在 FreeIPA 服务器上添加 Ubuntu 系统的 DNS 记录”">​</a></h4><p>登录到你的 FreeIPA 服务器并运行以下命令为 FreeIPA 客户端（即 Ubuntu 22.04/20.04）添加 DNS 记录：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ipa dnsrecord-add linuxtechi.lan app01.linuxtechi.lan --a-rec 192.168.1.106</span></span>
<span class="line"><span>  Record name: app01.linuxtechi.lan</span></span>
<span class="line"><span>  A record: 192.168.1.106</span></span>
<span class="line"><span>$</span></span></code></pre></div><p>在上面的命令中，<code>app01.linuxtechi.lan</code> 是我的 Ubuntu 系统，IP 地址为 <code>192.168.1.106</code>。</p><p>注意：确保你的 FreeIPA 服务器和客户端处于同一时区并从 NTP 服务器获取时间。</p><h4 id="_2、安装-freeipa-客户端包" tabindex="-1">2、安装 FreeIPA 客户端包 <a class="header-anchor" href="#_2、安装-freeipa-客户端包" aria-label="Permalink to “2、安装 FreeIPA 客户端包”">​</a></h4><p>从你的 Ubuntu 系统运行以下命令以安装 <code>freeipa-client</code> 以及依赖项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt install freeipa-client oddjob-mkhomedir -y</span></span></code></pre></div><p>在安装 <code>freeipa-client</code> 时，我们将看到以下页面，选择确定并回车。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/12/FreeIPA-Client-Kerberos-Auth-Ubuntu-Linux.png" alt=""></p><p>在下一个屏幕中，按回车键跳过。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/12/Skip-Kerberos-auth-freeipa-client-ubuntu.png" alt=""></p><h4 id="_3、在主机文件中添加-freeipa-服务器-ip-和主机名" tabindex="-1">3、在主机文件中添加 FreeIPA 服务器 IP 和主机名 <a class="header-anchor" href="#_3、在主机文件中添加-freeipa-服务器-ip-和主机名" aria-label="Permalink to “3、在主机文件中添加 FreeIPA 服务器 IP 和主机名”">​</a></h4><p>在 <code>/etc/hosts</code> 文件中添加以下 FreeIPA 服务器条目：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;192.168.1.102 ipa.linuxtechi.lan ipa&quot; | sudo tee -a /etc/hosts</span></span>
<span class="line"><span>$ echo &quot;192.168.1.106 app01.linuxtechi.lan app01&quot; | sudo tee -a /etc/hosts</span></span></code></pre></div><p>更改适合你的设置的 IP 地址和主机名。</p><h4 id="_4、使用-ipa-client-install-配置-freeipa-客户端" tabindex="-1">4、使用 ipa-client-install 配置 FreeIPA 客户端 <a class="header-anchor" href="#_4、使用-ipa-client-install-配置-freeipa-客户端" aria-label="Permalink to “4、使用 ipa-client-install 配置 FreeIPA 客户端”">​</a></h4><p>现在运行以下 <code>ipa-client-install</code> 命令在你的 Ubuntu 系统上配置 FreeIPA 客户端：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ipa-client-install --hostname=\`hostname -f\` --mkhomedir --server=ipa.linuxtechi.lan --domain linuxtechi.lan --realm LINUXTECHI.LAN</span></span></code></pre></div><p>更改适合你设置的 FreeIPA 服务器地址、域名和领域。</p><p>上述命令的输出如下所示：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/12/ipa-client-install-ubuntu-linux.png" alt=""></p><p>完美，上面的输出确认 FreeIPA 客户端安装成功。</p><p>现在允许在用户首次使用 FreeIPA 服务器进行身份验证时自动创建用户的主目录。</p><p>在文件 <code>/usr/share/pam-configs/mkhomedir</code> 中添加以下行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>required pam_mkhomedir.so umask=0022 skel=/etc/skel</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ echo &quot;required pam_mkhomedir.so umask=0022 skel=/etc/skel&quot; | sudo tee -a /usr/share/pam-configs/mkhomedir</span></span></code></pre></div><p>要使上述更改生效，请运行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pam-auth-update</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/12/Choose-Create-Home-Directory-on-login-Ubuntu-Pam.png" alt=""></p><p>选择确定，然后按回车键。</p><h4 id="_5、尝试使用-sysadm-用户登录到你的-ubuntu-系统" tabindex="-1">5、尝试使用 sysadm 用户登录到你的 Ubuntu 系统 <a class="header-anchor" href="#_5、尝试使用-sysadm-用户登录到你的-ubuntu-系统" aria-label="Permalink to “5、尝试使用 sysadm 用户登录到你的 Ubuntu 系统”">​</a></h4><p>尝试使用 <code>sysadm</code> 用户通过 SSH 登录到你的 Ubuntu 系统，</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sysadm@192.168.1.106</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/12/Set-New-Password-After-Expiry-FreeIPA-Client-Ubuntu-Linux.png" alt=""></p><p>正如你在上面看到的，当我们第一次登录时，它说密码已过期。它将提示我们设置新密码并断开会话。</p><p>更新密码后，尝试 SSH 登录 Ubuntu 系统，这次我们应该可以登录了。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ssh sysadm@192.168.1.106</span></span></code></pre></div><p>输出：</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2018/12/Centralize-Login-FreeIPA-Client-Ubuntu.png" alt=""></p><p>太好了，上面的输出确认我们已经使用集中用户成功登录到我们的 Ubuntu 系统。这也说明我们已经成功配置了 FreeIPA 客户端。</p><p>如果你想从 ubuntu 系统中卸载 FreeIPA，然后运行以下命令集：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo ipa-client-install --uninstall</span></span>
<span class="line"><span>$ sudo  rm -rf /var/lib/sss/db/*</span></span>
<span class="line"><span>$ sudo systemctl restart sssd.service</span></span></code></pre></div><p>以上就是这篇文章的全部内容，我相信你已经发现它提供了很多信息。请在下面发表你的疑问和反馈。</p><p><em>（题图：MJ/bd5b7777-f70a-4367-ac78-d026792b855a）</em></p><hr>`,56)),t("p",null,[s[1]||(s[1]=a("via: ",-1)),n(e,{href:"https://www.linuxtechi.com/configure-freeipa-client-on-ubuntu/"},{default:i(()=>[...s[0]||(s[0]=[a("https://www.linuxtechi.com/configure-freeipa-client-on-ubuntu/",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=a("作者：",-1)),n(e,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:i(()=>[...s[2]||(s[2]=[a("Pradeep Kumar",-1)])]),_:1}),s[7]||(s[7]=a(" 选题：",-1)),n(e,{href:"https://github.com/lkxed/"},{default:i(()=>[...s[3]||(s[3]=[a("lkxed",-1)])]),_:1}),s[8]||(s[8]=a(" 译者：",-1)),n(e,{href:"https://github.com/geekpi"},{default:i(()=>[...s[4]||(s[4]=[a("geekpi",-1)])]),_:1}),s[9]||(s[9]=a(" 校对：",-1)),n(e,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[a("LCTT",-1)])]),_:1}),s[13]||(s[13]=a(" 原创编译，",-1)),n(e,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[a("Linux中国",-1)])]),_:1}),s[14]||(s[14]=a(" 荣誉推出",-1))])])}const A=p(u,[["render",h]]);export{y as __pageData,A as default};
